package tilestest

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"slices"
	"strings"

	"github.com/baum-ai/baum/tiles"
)

// CheckGenerated checks a tile document generated by tiles.Compose from a
// normalized baum.review/1 document (review.NormalizeStored) and a
// composition, and returns every failure, each prefixed with the number of
// the invariant it breaks. It holds the invariants of CheckConversion, with
// these differences and additions:
//
//   - 1: as well, every change and everything_else tile of the converted
//     document is in the generated one, of the same type and covering the
//     same hunks, so no composition drops or empties one.
//   - 6: the risks tile is on the landing page whenever it ranks an active
//     critical or high risk (not otherwise required), and never in a group;
//     the overview tile is always on the landing page; neither is hidden.
//   - 8: a library or authored tile may be unavailable, with its problems.
//   - 11: a nil or empty composition gives the converted document's bytes;
//     any other gives origin "generated". At most tiles.MaxPromotions
//     promoted tiles (table and code tiles with an origin), one per change;
//     at most tiles.MaxAuthored authored tiles (other table, code and prose
//     tiles), each citing a hunk or file unless unavailable; at most
//     tiles.MaxLibraryTiles library tiles, each under its definition's name
//     (tiles.LibraryTileID).
//     A promoted or authored tile's ID is its type, an underscore and a
//     slug. Only current change tiles are in the changes group, only
//     obsolete ones in the obsolete group, and only tiles the composition's
//     layout hides in the hidden group; the obsolete group, then the hidden
//     one, come last. A change the recommendation names is never folded in
//     the changes group.
//   - 12: the encoded document passes the tile schema and the
//     document-level rules (tiles.Validator.Validate).
//   - 13: no row of a composed document, as the page lays it out
//     (tiles.Rows: a group a block of its own), ends with empty units that
//     growing its tiles to allowed sizes would fill (tiles.RowFills).
//   - 15: the landing page keeps tiles.LandingRows rows of tiles other than
//     the composition's library, promoted and authored tiles, unless those
//     take more than tiles.MaxExtraRows of its rows (tiles.ExtraRows).
//   - 14: the guard rails hold (tiles/guards.go): the first screen
//     (tiles.FirstScreenRows rows) and the landing page each show at least as
//     many current changes as the template's for the same review (with the same pins), unless it shows the
//     risks tile ranking a critical or high risk, a change the
//     recommendation names, the evidence tile with
//     tiles.EvidenceGapsShown gaps or a library tile with a destructive or
//     breaking item (tiles.Leads) that the template's does not, or a person
//     hid tiles; what must be seen on the template's first screen stays on
//     it, with a repository's pins applied to the template too; no change
//     is featured alone at half on a row another follows; and the evidence
//     tile with that many gaps is on the landing page, unless a person hid
//     it or the landing page holds only pinned tiles and those always on it.
//
// A layout a person edited (tiles.ApplyOverlay: layout.edited) is theirs:
// 14 does not apply to it, and 13 allows a row holding a tile they resized
// to end with empty units. Every other invariant holds whatever they edited,
// and so does this one (11): each tile the layout hides is in the last
// collapsed "Hidden tiles" group, unless it must be shown.
func CheckGenerated(normalized []byte, c *tiles.Composition, doc *tiles.Document) []string {
	failures := check(normalized, doc, true)
	fail := func(invariant int, format string, args ...any) {
		failures = append(failures, fmt.Sprintf("invariant %d: ", invariant)+fmt.Sprintf(format, args...))
	}

	converted, err := tiles.FromReview(normalized, tiles.Options{})
	if err != nil {
		return append(failures, "review: "+err.Error())
	}
	byID := map[string]*tiles.Tile{}
	for i := range doc.Tiles {
		byID[doc.Tiles[i].ID] = &doc.Tiles[i]
	}
	for _, want := range converted.Tiles {
		if want.Type != tiles.TypeChange && want.Type != tiles.TypeEverythingElse {
			continue
		}
		got := byID[want.ID]
		switch {
		case got == nil:
			fail(1, "the %s tile %s is missing", want.Type, want.ID)
		case got.Type != want.Type:
			fail(1, "tile %s is a %s tile, not a %s tile", want.ID, got.Type, want.Type)
		case !slices.Equal(got.Covers, want.Covers):
			fail(1, "tile %s covers %d hunks, %d when converted", want.ID, len(got.Covers), len(want.Covers))
		}
	}

	// 11. The composition's own rules.
	if c.Empty() {
		encoded, err := json.Marshal(doc)
		if err != nil {
			fail(11, "encoding: %v", err)
		}
		same := false
		for _, draft := range []bool{false, true} {
			want, err := tiles.FromReview(normalized, tiles.Options{Draft: draft})
			if err != nil {
				continue
			}
			if wantEncoded, err := json.Marshal(want); err == nil && bytes.Equal(encoded, wantEncoded) {
				same = true
			}
		}
		if !same {
			fail(11, "an empty composition does not give the converted document")
		}
	} else if doc.Origin.Kind != tiles.OriginGenerated {
		fail(11, "the origin is %q, not %q", doc.Origin.Kind, tiles.OriginGenerated)
	}
	promoted, authored, library := 0, 0, 0
	perChange := map[string]int{}
	for i := range doc.Tiles {
		tile := &doc.Tiles[i]
		switch {
		case tile.Type == tiles.TypeCustom:
			library++
			var def struct {
				Name string `json:"name"`
			}
			if json.Unmarshal(tile.Definition, &def) != nil || tiles.LibraryTileID(def.Name) != tile.ID {
				fail(11, "custom tile %s is not under its definition's name", tile.ID)
			}
		case !composed(tile) && promotedOrigin(tile) != nil:
			promoted++
			perChange[promotedOrigin(tile).Change]++
			if !composedID.MatchString(tile.ID) || !strings.HasPrefix(tile.ID, tile.Type+"_") {
				fail(11, "promoted tile %s does not have a %s_ ID", tile.ID, tile.Type)
			}
		case composed(tile):
			authored++
			if !composedID.MatchString(tile.ID) || !strings.HasPrefix(tile.ID, tile.Type+"_") {
				fail(11, "authored tile %s does not have a %s_ ID", tile.ID, tile.Type)
			}
			if tile.State != tiles.StateUnavailable && !citesCode(tile.Data) {
				fail(11, "authored tile %s cites no hunk or file", tile.ID)
			}
		}
	}
	if promoted > tiles.MaxPromotions {
		fail(11, "%d promoted tiles, more than %d", promoted, tiles.MaxPromotions)
	}
	for change, n := range perChange {
		if n > 1 {
			fail(11, "change %s has %d promoted blocks", change, n)
		}
	}
	if authored > tiles.MaxAuthored {
		fail(11, "%d authored tiles, more than %d", authored, tiles.MaxAuthored)
	}
	if library > tiles.MaxLibraryTiles {
		fail(11, "%d library tiles, more than %d", library, tiles.MaxLibraryTiles)
	}
	current := map[string]bool{}
	for _, change := range doc.Changes {
		var derived struct {
			State string `json:"state"`
		}
		_ = json.Unmarshal(change.Derived, &derived)
		current[change.ID] = derived.State != "stale"
	}
	hiddenByHost := map[string]bool{}
	if c != nil {
		for _, id := range c.Layout.Hidden {
			hiddenByHost[id] = true
		}
	}
	phase := map[string]int{"": 0, tiles.GroupChanges: 0, tiles.GroupObsolete: 1, tiles.GroupHidden: 2}
	reached := 0
	for _, entry := range doc.Layout.Entries {
		tile := byID[entry.Tile]
		if tile == nil {
			continue
		}
		switch entry.Group {
		case "":
		case tiles.GroupChanges:
			if tile.Type != tiles.TypeChange || !current[tile.ID] {
				fail(11, "tile %s is in the changes group but is not a current change", tile.ID)
			}
		case tiles.GroupObsolete:
			if tile.Type != tiles.TypeChange || current[tile.ID] {
				fail(11, "tile %s is in the obsolete group but is not an obsolete change", tile.ID)
			}
		case tiles.GroupHidden:
			if !hiddenByHost[tile.ID] {
				fail(11, "tile %s is hidden but the composition does not hide it", tile.ID)
			}
			if tile.ID == tiles.TypeOverview || tile.ID == tiles.TypeRisks && severeRanked(doc) || slices.Contains(tiles.RecommendedChanges(doc), tile.ID) {
				fail(6, "tile %s is hidden but must be shown", tile.ID)
			}
		default:
			fail(11, "tile %s is in group %s, which a composition cannot set", tile.ID, entry.Group)
		}
		if p, ok := phase[entry.Group]; ok {
			if p < reached {
				fail(11, "tile %s comes after the obsolete or hidden tiles", tile.ID)
			}
			reached = max(reached, p)
		}
	}
	// A change the recommendation names is not folded away in the changes
	// group.
	if !c.Empty() {
		hidden := tiles.Hidden(doc.Layout)
		named := tiles.RecommendedChanges(doc)
		for i, entry := range doc.Layout.Entries {
			if entry.Group == tiles.GroupChanges && hidden[i] && slices.Contains(named, entry.Tile) {
				fail(11, "change %s, which the recommendation names, is folded in the changes group", entry.Tile)
			}
		}
	}

	// An edited or pinned layout keeps a change the recommendation names,
	// outside the changes group, on the landing page; an unedited, unpinned
	// one does through the guards and invariants above.
	if !c.Empty() && (c.Layout.Edited || slices.ContainsFunc(doc.Layout.Entries, func(e tiles.Entry) bool { return e.Pin })) {
		for i, entry := range doc.Layout.Entries {
			if entry.Group != tiles.GroupChanges && entry.Group != tiles.GroupHidden && entry.Group != tiles.GroupObsolete &&
				slices.Contains(tiles.RecommendedChanges(doc), entry.Tile) && !tiles.Visible(doc.Layout)[i] {
				fail(11, "change %s, which the recommendation names, is off the landing page of an edited or pinned layout", entry.Tile)
			}
		}
	}

	// Hidden tiles stay reachable, in the last collapsed group.
	if c != nil && len(c.Layout.Hidden) > 0 {
		for _, id := range c.Layout.Hidden {
			obsolete := slices.ContainsFunc(doc.Layout.Entries, func(e tiles.Entry) bool { return e.Tile == id && e.Group == tiles.GroupObsolete })
			if byID[id] == nil || obsolete || id == tiles.TypeOverview || id == tiles.TypeRisks && severeRanked(doc) || slices.Contains(tiles.RecommendedChanges(doc), id) {
				continue
			}
			if !slices.ContainsFunc(doc.Layout.Entries, func(e tiles.Entry) bool { return e.Tile == id && e.Group == tiles.GroupHidden }) {
				fail(11, "tile %s is hidden but not in the hidden group", id)
			}
		}
		at := slices.IndexFunc(doc.Layout.Groups, func(g tiles.Group) bool { return g.ID == tiles.GroupHidden })
		hasHidden := slices.ContainsFunc(doc.Layout.Entries, func(e tiles.Entry) bool { return e.Group == tiles.GroupHidden })
		if hasHidden && (at != len(doc.Layout.Groups)-1 || doc.Layout.Groups[at].CollapseAfter == nil || *doc.Layout.Groups[at].CollapseAfter != 0) {
			fail(11, "the hidden tiles are not in a last collapsed group")
		}
	}

	// 13. Rows are filled where they can be: a person's resized rows are
	// theirs.
	if !c.Empty() {
		kept := personsRows(doc, c)
		for id, size := range tiles.RowFills(doc) {
			if !kept[id] {
				fail(13, "tile %s ends a row with empty units; at %s it would fill it", id, size)
			}
		}
	}

	// 15. Library, promoted and authored tiles add to the landing page: it
	// keeps tiles.LandingRows rows of other tiles (as many as there are),
	// unless they take more than tiles.MaxExtraRows rows.
	if !c.Empty() {
		extra := map[string]bool{}
		for _, tile := range doc.Tiles {
			if tiles.Extra(tile) {
				extra[tile.ID] = true
			}
		}
		own, taken, total := 0, 0, 0
		for _, row := range tiles.Rows(doc.Layout) {
			has := slices.ContainsFunc(row.Entries, func(i int) bool { return extra[doc.Layout.Entries[i].Tile] })
			if !has {
				total++
			}
			if row.Entries[0] >= doc.Layout.Landing {
				continue
			}
			if has {
				taken++
			} else {
				own++
			}
		}
		if own < min(tiles.LandingRows, total) && taken <= tiles.MaxExtraRows {
			fail(15, "the landing page keeps %d rows of tiles other than the composition's, not %d", own, min(tiles.LandingRows, total))
		}
	}

	// 14. The guard rails, which leave a person's edited layout alone.
	if !c.Empty() && !c.Layout.Edited {
		for _, failure := range guardFailures(converted, c, doc) {
			fail(14, "%s", failure)
		}
	}

	// 12. The document validates.
	encoded, err := json.Marshal(doc)
	if err != nil {
		fail(12, "encoding: %v", err)
	} else if _, err := validator.Validate(encoded); err != nil {
		var invalid *tiles.DocumentError
		if errors.As(err, &invalid) {
			for _, problem := range invalid.Problems {
				fail(12, "%s", problem)
			}
		} else {
			fail(12, "%v", err)
		}
	}
	return failures
}

// personsRows returns the tiles of the rows of an edited layout that hold a
// tile the person resized.
func personsRows(doc *tiles.Document, c *tiles.Composition) map[string]bool {
	kept := map[string]bool{}
	if !c.Layout.Edited {
		return kept
	}
	for _, row := range tiles.Rows(doc.Layout) {
		held := false
		for _, i := range row.Entries {
			held = held || slices.Contains(c.Layout.Resized, doc.Layout.Entries[i].Tile)
		}
		for _, i := range row.Entries {
			if held {
				kept[doc.Layout.Entries[i].Tile] = true
			}
		}
	}
	return kept
}

// severeRanked reports whether the risks tile ranks an active critical or
// high risk.
func severeRanked(doc *tiles.Document) bool {
	severe := map[string]bool{}
	for _, risk := range doc.Risks {
		if risk.State == "active" && (risk.Tier == "critical" || risk.Tier == "high") {
			severe[risk.ID] = true
		}
	}
	for _, tile := range doc.Tiles {
		if tile.Type != tiles.TypeRisks {
			continue
		}
		var data tiles.RisksData
		_ = json.Unmarshal(tile.Data, &data)
		for _, id := range data.Ranked {
			if severe[id] {
				return true
			}
		}
	}
	return false
}

var composedID = regexp.MustCompile(`^(table|code|prose)_[a-z0-9_]{1,64}$`)

// composed reports whether a tile is a library or authored tile: a custom
// tile, or a table, code or prose tile without an origin.
func composed(tile *tiles.Tile) bool {
	switch tile.Type {
	case tiles.TypeCustom, tiles.TypeProse:
		return true
	case tiles.TypeTable, tiles.TypeCode:
		return promotedOrigin(tile) == nil
	}
	return false
}

// promotedOrigin returns a promoted table or code tile's origin, or nil.
func promotedOrigin(tile *tiles.Tile) *tiles.BlockOrigin {
	var data struct {
		Origin *tiles.BlockOrigin `json:"origin"`
	}
	if json.Unmarshal(tile.Data, &data) != nil {
		return nil
	}
	return data.Origin
}

// citesCode reports whether data holds a hunk or file anchor in its source
// or anchors.
func citesCode(data json.RawMessage) bool {
	var value struct {
		Source  []anchorType `json:"source"`
		Anchors []anchorType `json:"anchors"`
	}
	_ = json.Unmarshal(data, &value)
	return slices.ContainsFunc(append(value.Source, value.Anchors...), func(a anchorType) bool {
		return a.Type == "hunk" || a.Type == "file"
	})
}

type anchorType struct {
	Type string `json:"type"`
}

// stableSubject is what a tile two versions share must keep: its type and,
// for a promoted tile, its origin's change; an authored tile's subject is
// "authored".
func stableSubject(tile *tiles.Tile) string {
	switch {
	case tile.Type == tiles.TypeCustom:
		var def struct {
			Name string `json:"name"`
		}
		_ = json.Unmarshal(tile.Definition, &def)
		return "custom " + def.Name
	case (tile.Type == tiles.TypeTable || tile.Type == tiles.TypeCode) && promotedOrigin(tile) != nil:
		return tile.Type + " promoted from " + promotedOrigin(tile).Change
	case composed(tile):
		return tile.Type + " authored"
	}
	return tile.Type
}

// screenFacts is what the first screen of a document shows: its current
// changes, and the tiles that may stand in for them.
type screenFacts struct {
	changes, landing int
	others           map[string]bool
}

func firstScreenFacts(doc *tiles.Document) screenFacts {
	current := map[string]bool{}
	for _, change := range doc.Changes {
		var derived struct {
			State string `json:"state"`
		}
		_ = json.Unmarshal(change.Derived, &derived)
		current[change.ID] = derived.State != "stale"
	}
	named := tiles.RecommendedChanges(doc)
	gaps := evidenceGaps(doc, current)
	leads := map[string]bool{}
	for _, tile := range doc.Tiles {
		if tile.Type == tiles.TypeCustom && tile.State == tiles.StateReady && tiles.Leads(tile.Data) {
			leads[tile.ID] = true
		}
	}
	out := screenFacts{others: map[string]bool{}}
	visible := tiles.Visible(doc.Layout)
	for i, entry := range doc.Layout.Entries {
		if visible[i] && current[entry.Tile] {
			out.landing++
		}
	}
	for k, row := range tiles.Rows(doc.Layout) {
		if k >= tiles.FirstScreenRows || row.Entries[0] >= doc.Layout.Landing {
			break
		}
		for _, i := range row.Entries {
			entry := doc.Layout.Entries[i]
			if current[entry.Tile] {
				out.changes++
			}
			if entry.Pin || entry.Tile == tiles.TypeRisks && severeRanked(doc) || slices.Contains(named, entry.Tile) ||
				entry.Tile == tiles.TypeEvidence && gaps >= tiles.EvidenceGapsShown || leads[entry.Tile] {
				out.others[entry.Tile] = true
			}
		}
	}
	return out
}

func evidenceGaps(doc *tiles.Document, current map[string]bool) int {
	n := 0
	for _, item := range doc.Evidence {
		if current[item.Change] && (item.Status == "missing" || item.Status == "failed") {
			n++
		}
	}
	return n
}

// guardFailures checks the guard rails of a document composed from a
// converted one against the template of the same review.
func guardFailures(converted *tiles.Document, c *tiles.Composition, doc *tiles.Document) []string {
	var failures []string
	template, _ := tiles.Template(converted, c)
	// A repository's pins are honoured by both layouts: the template is
	// compared with the same pins applied.
	var pins []string
	for _, e := range c.Layout.Entries {
		if e.Pin {
			pins = append(pins, e.Tile)
		}
	}
	template.Layout.Entries = tiles.PinEntries(template.Layout.Entries, converted, pins)
	templated, err := tiles.Compose(converted, &template)
	if err != nil {
		return []string{"the template does not compose: " + err.Error()}
	}
	got, want := firstScreenFacts(doc), firstScreenFacts(templated)
	if len(c.Layout.Hidden) == 0 {
		for id := range want.others {
			if !got.others[id] {
				failures = append(failures, fmt.Sprintf("tile %s, which must be seen, is on the template's first screen and not on this one", id))
			}
		}
	}
	if (got.changes < want.changes || got.landing < want.landing) && len(c.Layout.Hidden) == 0 {
		standsIn := false
		for id := range got.others {
			standsIn = standsIn || !want.others[id]
		}
		if !standsIn {
			failures = append(failures, fmt.Sprintf("the first screen shows %d changes and the landing page %d, the template's %d and %d, and nothing that must be seen instead",
				got.changes, got.landing, want.changes, want.landing))
		}
	}
	rows := tiles.Rows(doc.Layout)
	for k, row := range rows {
		if len(row.Entries) != 1 || row.Group != "" || k == len(rows)-1 {
			continue
		}
		entry := doc.Layout.Entries[row.Entries[0]]
		if entry.Size == tiles.SizeHalf && !entry.Pin && slices.ContainsFunc(doc.Changes, func(change tiles.Change) bool { return change.ID == entry.Tile }) {
			failures = append(failures, fmt.Sprintf("change %s is featured alone at half", entry.Tile))
		}
	}
	current := map[string]bool{}
	for _, change := range doc.Changes {
		var derived struct {
			State string `json:"state"`
		}
		_ = json.Unmarshal(change.Derived, &derived)
		current[change.ID] = derived.State != "stale"
	}
	if evidenceGaps(doc, current) >= tiles.EvidenceGapsShown && !slices.Contains(c.Layout.Hidden, tiles.TypeEvidence) {
		visible := tiles.Visible(doc.Layout)
		// No place is left when the landing page holds only pinned tiles and
		// those always on it (the overview, the risks and the changes the
		// recommendation names).
		// A landing page that four or more pinned tiles share is the
		// repository's: the evidence has no place there either.
		pinned := 0
		full := true
		for i, entry := range doc.Layout.Entries {
			if visible[i] && entry.Pin {
				pinned++
			}
			if visible[i] && !entry.Pin && entry.Tile != tiles.TypeOverview && entry.Tile != tiles.TypeRisks && !slices.Contains(tiles.RecommendedChanges(doc), entry.Tile) {
				full = false
			}
		}
		full = full || pinned >= 4
		for i, entry := range doc.Layout.Entries {
			if entry.Tile == tiles.TypeEvidence && !visible[i] && !full {
				failures = append(failures, "the evidence tile has gaps and is not on the landing page")
			}
		}
	}
	return failures
}
